import torch as t

def solve(m,x):
    flagged=[]
    def check(module,inputs,output):
        if t.isnan(output).any():
            flagged.append(module)
    def add_hook(module):
        module.register_forward_hook(check)
    m.apply(add_hook)
    m(x)
    return len(flagged)

